#!/usr/bin/env bash
# Install autoconf 2.72 into ~/.local so that a Buildroot build finds it
# before the system one.
#
# Why this is needed:
#
# Buildroot runs autoreconf for util-linux (UTIL_LINUX_AUTORECONF = YES).
# util-linux 2.40.4 ships a configure that was generated by autoconf 2.72.
# Regenerating it with the autoconf 2.71 of Ubuntu 22.04 changes how
# PACKAGE_STRING is defined, and the build fails with
#
#     include/c.h:482:78: error: 'PACKAGE_STRING' undeclared
#
# The work happens under $HOME because /tmp in WSL2 is volatile, it is
# cleared when the distribution stops.
#
# Runs inside WSL2.
set -uo pipefail

VERSION="${AUTOCONF_VERSION:-2.72}"
PREFIX="${PREFIX:-$HOME/.local}"
WORK="${HOME}/.cache/autoconf-build"

mkdir -p "${WORK}" "${PREFIX}"
cd "${WORK}"

if [ -x "${PREFIX}/bin/autoconf" ] && \
   "${PREFIX}/bin/autoconf" --version 2>/dev/null | grep -q "2\.7[2-9]"; then
    echo "autoconf is already in place:"
    "${PREFIX}/bin/autoconf" --version | head -1
    exit 0
fi

tarball="autoconf-${VERSION}.tar.xz"
if [ ! -s "${tarball}" ]; then
    for base in \
        https://mirrors.tuna.tsinghua.edu.cn/gnu/autoconf \
        https://mirrors.aliyun.com/gnu/autoconf \
        https://mirror.nju.edu.cn/gnu/autoconf \
        https://ftpmirror.gnu.org/autoconf \
        https://ftp.gnu.org/gnu/autoconf ; do
        echo "Trying ${base}"
        if curl -fsSL --connect-timeout 10 --max-time 240 \
                -o "${tarball}" "${base}/${tarball}" 2>/dev/null && \
           [ -s "${tarball}" ]; then
            echo "  got $(du -h "${tarball}" | cut -f1)"
            break
        fi
        rm -f "${tarball}"
    done
fi

if [ ! -s "${tarball}" ]; then
    echo "Could not download autoconf ${VERSION}" >&2
    exit 1
fi

rm -rf "autoconf-${VERSION}"
tar xf "${tarball}"
cd "autoconf-${VERSION}"

echo "Configuring"
./configure --prefix="${PREFIX}" > configure.log 2>&1 || {
    tail -20 configure.log >&2
    exit 1
}

echo "Building"
make -j"$(nproc)" > make.log 2>&1 || {
    tail -30 make.log >&2
    exit 1
}

echo "Installing"
make install > install.log 2>&1 || {
    tail -20 install.log >&2
    exit 1
}

"${PREFIX}/bin/autoconf" --version | head -1
echo "Installed into ${PREFIX}"
